contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger, bool status, address keepAddr) public {
        c.setApprovedLogger(logger, status);
        bool observed = c.approvedToLog(logger);
        bool ok;
        if (logger == address(this)) {
            ok = c.logCreated(keepAddr);
        } else {
            // msg.sender is this contract, so simulate the logger via its own view only;
            // instead check this contract's own logging path when not approved.
            bool selfApproved = c.approvedToLog(address(this));
            bool selfResult = c.logCreated(keepAddr);
            assert(selfResult == selfApproved);
            assert(observed == status);
            return;
        }
        assert(observed == status && ok == status);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address keepAddr, bool status) public {
        c.setApprovedLogger(address(this), status);
        bool logged = c.logCreated(keepAddr);
        bool approved = c.approvedToLog(address(this));
        assert(logged == status && approved == status);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
