contract InvMutTest {
    C c;
    constructor(C _c) { c = c_is(_c); }
    function c_is(C _c) internal returns (C) { c = _c; return _c; }
    function run(address other, bool otherStatus) public {
        c.setApprovedLogger(other, otherStatus);
        bool approvedOther = c.approvedToLog(other);
        bool okBefore = c.logLiquidated();
        c.setApprovedLogger(address(this), true);
        bool okAfter = c.logLiquidated();
        assert(approvedOther == otherStatus && okBefore == false && okAfter == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _logger, bytes32 _txid, bool _status) public {
        // _logger is queried but only address(this) can act as msg.sender on c.
        bool approvedBefore = c.approvedToLog(address(this));
        bool r1 = c.logRedeemed(_txid);
        assert(r1 == approvedBefore);
        // If this contract is the owner, flip approval and verify the return value tracks approval.
        // Otherwise, the rule still must hold: returns equal approvedToLog.
        bool r2 = c.logFunded();
        assert(r2 == c.approvedToLog(address(this)));
        assert(r1 == r2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 _txid) public {
        bool approved = c.approvedToLog(address(this));
        bool r = c.logRedeemed(_txid);
        assert(!approved && !r && !c.approvedToLog(address(this)));
    }
    receive() external payable {}
}
